<script module lang="ts">
/**
 * A changed value or text, shown as old and new (`design/components/diff.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/diff.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import { devWarning, diffLines, diffRuns, joinSlot, watchEffect } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/diff.module.css'
import Button from '../controls/Button.svelte'

export interface DiffMessages {
  /** Read before the old value of a value that changed: "from". */
  from: string
  /** Read between the old value and the new one: "to". */
  to: string
  /** Read before a value, or a line, that only the new side has. */
  added: string
  /** Read before a value, or a line, that only the old side has. */
  removed: string
  /** A collapsed run's Button. */
  unchanged: (count: number) => string
}

export interface DiffProps {
  /**
   * The new value. Missing, `null` or empty means there is none: with a `before`, the change is
   * a removal. Equal sides are no change.
   */
  after?: string | null
  /**
   * The old value. Missing, `null` or empty means there was none: with an `after`, the change is
   * an addition.
   */
  before?: string | null
  /**
   * In `lines`, the unchanged lines kept beside each change. The unchanged lines past them are
   * one row that says how many it holds and shows them when pressed. `Infinity` keeps every
   * line.
   */
  context?: number
  /**
   * `inline` (the default) is a short value inside a sentence or a cell. `lines` compares two
   * texts of several lines, line by line.
   */
  display?: 'inline' | 'lines'
  /**
   * Names the `lines` form, which is a region. The `lines` form needs it; `inline` does not use
   * it.
   */
  label?: string
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: DiffMessages
}
</script>

<script lang="ts">
let {
  after,
  before,
  context = 3,
  display = 'inline',
  label: labelOwn,
  messages = (() => ({
    from: 'from',
    to: 'to',
    added: 'added',
    removed: 'removed',
    unchanged: (count: number) => `${count} unchanged ${count === 1 ? 'line' : 'lines'}`,
  }))(),
}: DiffProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
let opened = $state([] as number[])
const old = $derived(before ?? '')
const next = $derived(after ?? '')
const runs = $derived(display === 'lines' ? diffRuns(diffLines(old, next), context) : [])
const effect1 = () => {
  devWarning(
    display === 'lines' && label === undefined,
    'Diff: the `lines` form is a region, and a region needs a name; pass `label`.',
  )
}
watchEffect(effect1, { watch: () => display === 'lines' && label === undefined })
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#if old !== '' || next !== ''
    }{#if display === 'lines'
      }<section class={styles.lines} aria-label={label} data-member="diff"
        ><ol class={styles.rows} role="list"
          >{#each runs as piece (piece.key)
            }{#if piece.collapsed
              }<li class={styles.run}
                ><div class={styles.fold}
                  ><Button
                    variant="ghost"
                    tone="neutral"
                    size="sm"
                    icon={opened.includes(piece.key) ? 'collapse' : 'expand'}
                    label={messages.unchanged(piece.rows.length)}
                    expanded={opened.includes(piece.key)}
                    aria-controls={opened.includes(piece.key) ? `${uid}-run-${piece.key}` : undefined}
                    onClick={() => { opened = opened.includes(piece.key) ? opened.filter((key) => key !== piece.key) : [...opened, piece.key] }}
                /></div
                >{#if opened.includes(piece.key)
                  }<ol class={styles.rows} id={`${uid}-run-${piece.key}`} role="list"
                    >{#each piece.rows as row (row.kind === 'removed' ? `r${row.beforeLine}` : `${row.kind === 'added' ? 'a' : 's'}${row.afterLine}`)
                      }<li class={styles.row} data-kind={row.kind === 'same' ? undefined : row.kind}
                        ><span class={styles.marker} aria-hidden="true"
                          >{row.kind === 'added' ? '+' : row.kind === 'removed' ? '−' : ''
                        }</span
                        >{#if row.kind !== 'same'
                          }<span class={styles.spoken}
                            >{(row.kind === 'added' ? messages.added : messages.removed) + ' '
                          }</span
                        >{/if
                        }<span class={styles.text}>{row.text}</span
                      ></li
                    >{/each
                  }</ol
                >{/if
              }</li
            >{:else
              }{#each piece.rows as row (row.kind === 'removed' ? `r${row.beforeLine}` : `${row.kind === 'added' ? 'a' : 's'}${row.afterLine}`)
                }<li class={styles.row} data-kind={row.kind === 'same' ? undefined : row.kind}
                  ><span class={styles.marker} aria-hidden="true"
                    >{row.kind === 'added' ? '+' : row.kind === 'removed' ? '−' : ''
                  }</span
                  >{#if row.kind !== 'same'
                    }<span class={styles.spoken}
                      >{(row.kind === 'added' ? messages.added : messages.removed) + ' '
                    }</span
                  >{/if
                  }<span class={styles.text}>{row.text}</span
                ></li
              >{/each
            }{/if
          }{/each
        }</ol
      ></section
    >{:else if old === next
      }<span class={styles.inline} data-member="diff">{next}</span
    >{:else if old === ''
      }<span class={styles.inline} data-member="diff"
        ><span class={styles.spoken}>{messages.added + ' '}</span
        ><span class={styles.sign} aria-hidden="true">{'+'}</span
        ><ins class={styles.after}>{next}</ins
      ></span
    >{:else if next === ''
      }<span class={styles.inline} data-member="diff"
        ><span class={styles.spoken}>{messages.removed + ' '}</span
        ><del class={styles.before}>{old}</del
      ></span
    >{:else
      }<span class={styles.inline} data-member="diff"
        ><span class={styles.spoken}>{messages.from + ' '}</span
        ><del class={styles.before}>{old}</del
        ><span class={styles.arrow} aria-hidden="true">{'→'}</span
        ><span class={styles.spoken}>{' ' + messages.to + ' '}</span
        ><ins class={styles.after}>{next}</ins
      ></span
    >{/if
  }{/if
}{/if
}{@render joined.end?.()}
